<?php
$where='1=1';$args=[];$q=mb_substr(trim((string)($_GET['q']??'')),0,100);$action=(string)($_GET['activity']??'');$operator=(int)($_GET['operator']??0);[$from,$to]=listDateRange();
if($action!==''){$where.=' AND a.action=?';$args[]=$action;}if($operator){$where.=' AND a.user_id=?';$args[]=$operator;}if($from!==''){$where.=' AND a.created_at>=?';$args[]=$from;}if($to!==''){$where.=' AND a.created_at<?';$args[]=(new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d');}
if($q!==''){$matches=[];foreach(activityNames() as $key=>$name)if(mb_stripos($name,$q)!==false)$matches[]=$key;$where.=' AND (a.details LIKE ? OR u.name LIKE ? OR CAST(a.entity_id AS CHAR) LIKE ?';array_push($args,'%'.$q.'%','%'.$q.'%','%'.$q.'%');if($matches){$where.=' OR a.action IN ('.implode(',',array_fill(0,count($matches),'?')).')';array_push($args,...$matches);}$where.=')';}
$p=max(1,min(10000,(int)($_GET['p']??1)));$offset=($p-1)*50;$count=(int)query("SELECT COUNT(*) FROM audit_log a LEFT JOIN users u ON u.id=a.user_id WHERE $where",$args)->fetchColumn();
?>
<div class="page-title"><div><p class="eyebrow">EVIDENCIJA I ODGOVORNOST</p><h1>Dnevnik aktivnosti</h1><p>Ko je izvršio promjenu, kada i s kojim obrazloženjem.</p></div><span class="date-chip"><?=$count?> zapisa</span></div>
<section class="panel"><form method="get" class="admin-filters"><input type="hidden" name="page" value="audit"><div><?php field('q','Pretraga aktivnosti ili obrazloženja',$q,'text',false);?></div><div><?php selectField('activity','Aktivnost',[''=>'Sve aktivnosti']+activityNames(),$action);?></div><div><?php $users=[0=>'Svi korisnici'];foreach(query('SELECT id,name FROM users ORDER BY name')->fetchAll() as $user)$users[$user['id']]=$user['name'];selectField('operator','Korisnik',$users,$operator);?></div><div><?php field('from','Datum od',$from,'date',false);?></div><div><?php field('to','Datum do',$to,'date',false);?></div><button>Prikaži</button></form><div class="table-scroll"><table><thead><tr><th>Vrijeme</th><th>Korisnik</th><th>Aktivnost</th><th>Obrazloženje i evidencija</th></tr></thead><tbody><?php foreach(query("SELECT a.*,u.name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id WHERE $where ORDER BY a.id DESC LIMIT 50 OFFSET $offset",$args)->fetchAll() as $row):?><tr><td><?=e(date('d.m.Y. H:i:s',strtotime($row['created_at'])))?></td><td><?=e($row['name']??'Sistem / kupac')?></td><td><strong><?=e(activityLabel($row['action']))?></strong></td><td><?=nl2br(e(activityDetails($row)))?></td></tr><?php endforeach;?></tbody></table></div><div class="list-pagination"><span>Stranica <?=$p?> / <?=max(1,(int)ceil($count/50))?></span><?php foreach([-1=>'← Prethodna',1=>'Sljedeća →'] as $delta=>$label)if(($delta<0&&$p>1)||($delta>0&&$offset+50<$count)):?><a href="?<?=e(http_build_query(array_merge($_GET,['p'=>$p+$delta])))?>"><?=$label?></a><?php endif;?></div></section>
